<script module lang="ts">
/**
 * Markdown.Blocks: a reply’s blocks, each as the member that draws its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { inlineText, joinSlot, markdownHeadingLevel, type MarkdownBlock } from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import CodeBlock from '../structure/CodeBlock.svelte'
import Heading from '../structure/Heading.svelte'
import MarkdownBlocks from './MarkdownBlocks.svelte'
import MarkdownInlines from './MarkdownInlines.svelte'
import Separator from '../structure/Separator.svelte'
import Table from '../structure/Table.svelte'
import TableBody from '../structure/TableBody.svelte'
import TableCell from '../structure/TableCell.svelte'
import TableHead from '../structure/TableHead.svelte'
import TableHeader from '../structure/TableHeader.svelte'
import TableRow from '../structure/TableRow.svelte'
import Text from '../structure/Text.svelte'
import type { CitationSource } from './SourceList.svelte'

export interface MarkdownBlocksProps {
  blocks: MarkdownBlock[]
  size: 'sm' | 'md'
  sources: CitationSource[]
  /**
   * The shallowest heading depth in the reply, which is level 2.
   */
  shallowest: number
  /**
   * Whether the caret ends the last block.
   */
  caret: boolean
}
</script>

<script lang="ts">
let { blocks, size, sources, shallowest, caret }: MarkdownBlocksProps = $props()
const joined = joinSlot(undefined, () => ({ size: size }))
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#each blocks as block, index (index)
    }{#if block.kind === 'paragraph'
      }<Text {size}
        ><MarkdownInlines nodes={block.children} {sources}
        />{#if caret && index === blocks.length - 1
          }<span class={styles.caret} aria-hidden="true"></span
        >{/if
      }</Text
    >{:else if block.kind === 'heading'
      }<Heading level={markdownHeadingLevel(block.depth, shallowest)}
        >{inlineText(block.children)
      }</Heading
    >{:else if block.kind === 'code'
      }<CodeBlock copyable={block.closed}>{block.text}</CodeBlock
    >{:else if block.kind === 'quote'
      }<blockquote class={styles.quote}
        ><MarkdownBlocks
          blocks={block.children}
          {size}
          {sources}
          {shallowest}
          caret={caret && index === blocks.length - 1}
      /></blockquote
    >{:else if block.kind === 'list'
      }<svelte:element
        this={block.ordered ? 'ol' : 'ul'}
        class={styles.list}
        start={block.ordered && block.start !== 1 ? block.start : undefined}
        >{#each block.items as item, position (position)
          }<li class={styles.item}
            ><MarkdownBlocks
              blocks={item}
              {size}
              {sources}
              {shallowest}
              caret={caret && index === blocks.length - 1 && position === block.items.length - 1}
          /></li
        >{/each
      }</svelte:element
    >{:else if block.kind === 'table'
      }<Table
        ><TableHead
          ><TableRow
            >{#each block.header as head, column (column)
              }<TableHeader numeric={block.align[column] === 'end'}
                ><MarkdownInlines nodes={head} {sources}
              /></TableHeader
            >{/each
          }</TableRow
        ></TableHead
        ><TableBody
          >{#each block.rows as row, line (line)
            }<TableRow
              >{#each row as value, column (column)
                }<TableCell numeric={block.align[column] === 'end'}
                  ><MarkdownInlines nodes={value} {sources}
                /></TableCell
              >{/each
            }</TableRow
          >{/each
        }</TableBody
      ></Table
    >{:else if block.kind === 'rule'
      }<Separator
    />{/if
  }{/each
}{/if
}{@render joined.end?.()}
